package com.bobmowzie.mowziesmobs.server.entity.elokosa;

import com.bobmowzie.mowziesmobs.client.particle.ParticleHandler;
import com.bobmowzie.mowziesmobs.server.potion.EffectHandler;
import com.google.common.base.Defaults;
import net.minecraft.core.Holder;
import net.minecraft.core.particles.ParticleType;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffects;

import java.util.EnumMap;
import java.util.Locale;

public enum PawType {
    FULL(MobEffects.WEAKNESS, ParticleHandler.MOON_FULL),
    GIBBOUS(MobEffects.MOVEMENT_SLOWDOWN, ParticleHandler.MOON_GIBBOUS),
    HALF(MobEffects.DIG_SLOWDOWN, ParticleHandler.MOON_HALF),
    CRESCENT(EffectHandler.FRAGILITY, ParticleHandler.MOON_CRESCENT),
    NEW(EffectHandler.ECLIPSED, ParticleHandler.MOON_NEW);

    public static final int COUNT = PawType.values().length;

    private final Holder<MobEffect> potion;
    private final Holder<ParticleType<?>> particleType;

    private final String name;

    PawType(Holder<MobEffect> potion, Holder<ParticleType<?>> particleType) {
        this.potion = potion;
        this.particleType = particleType;
        name = name().toLowerCase(Locale.ENGLISH);
    }

    public static PawType from(int id) {
        if (id < 0 || id >= COUNT) {
            return NEW;
        }
        return values()[id];
    }

    public static <T> EnumMap<PawType, T> newEnumMap(Class<T> type, T... defaultValues) {
        EnumMap map = new EnumMap<PawType, T>(PawType.class);
        PawType[] paws = values();
        for (int i = 0; i < paws.length; i++) {
            map.put(paws[i], i >= 0 && i < defaultValues.length ? defaultValues[i] : Defaults.defaultValue(type));
        }
        return map;
    }

    public String getName() {
        return name;
    }

    public Holder<MobEffect> getPotion() {
        return potion;
    }

    public Holder<ParticleType<?>> getParticleType() {
        return particleType;
    }
}

package com.bobmowzie.mowziesmobs.server.capability;

import com.google.common.collect.Maps;
import net.minecraft.core.Holder;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.LivingEntity;
import net.neoforged.neoforge.common.util.INBTSerializable;
import org.jetbrains.annotations.NotNull;

import java.util.Map;

public class LivingData implements INBTSerializable<CompoundTag> {
    float lastDamage = 0;
    boolean hasSunblock;
    private final Map<Holder<MobEffect>, MobEffectInstance> eclipsedEffects = Maps.newHashMap();

    public void setLastDamage(float damage) {
        lastDamage = damage;
    }

    public float getLastDamage() {
        return lastDamage;
    }

    public void setHasSunblock(boolean hasSunblock) {
        this.hasSunblock = hasSunblock;
    }

    public boolean getHasSunblock() {
        return hasSunblock;
    }

    public void tick(LivingEntity entity) {
//            if (!hasSunblock && entity.isPotionActive(EffectHandler.SUNBLOCK)) hasSunblock = true;
    }

    public void eclipseEffect(MobEffectInstance mobEffectInstance) {
        eclipsedEffects.put(mobEffectInstance.getEffect(), mobEffectInstance);
    }

    public void unEclipseEffects(LivingEntity entity) {
        if (!this.eclipsedEffects.isEmpty()) {
            for (MobEffectInstance mobeffectinstance : this.eclipsedEffects.values()) {
                entity.addEffect(mobeffectinstance);
            }
            this.eclipsedEffects.clear();
        }
    }

    @Override
    public CompoundTag serializeNBT(@NotNull HolderLookup.Provider lookup) {
        CompoundTag compound = new CompoundTag();
        if (!this.eclipsedEffects.isEmpty()) {
            ListTag listtag = new ListTag();

            for (MobEffectInstance mobeffectinstance : this.eclipsedEffects.values()) {
                listtag.add(mobeffectinstance.save());
            }

            compound.put("eclipsed_effects", listtag);
        }
        return compound;
    }

    @Override
    public void deserializeNBT(@NotNull HolderLookup.Provider lookup, @NotNull CompoundTag compound) {
        if (compound.contains("eclipsed_effects", 9)) {
            ListTag listtag = compound.getList("eclipsed_effects", 10);

            for (int i = 0; i < listtag.size(); i++) {
                CompoundTag compoundtag = listtag.getCompound(i);
                MobEffectInstance mobeffectinstance = MobEffectInstance.load(compoundtag);
                if (mobeffectinstance != null) {
                    this.eclipsedEffects.put(mobeffectinstance.getEffect(), mobeffectinstance);
                }
            }
        }
    }
}

package com.bobmowzie.mowziesmobs.server.potion;

import com.bobmowzie.mowziesmobs.MMCommon;
import net.minecraft.core.Holder;
import net.minecraft.core.registries.Registries;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.LivingEntity;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

public final class EffectHandler {
	public static final DeferredRegister<MobEffect> REG = DeferredRegister.create(Registries.MOB_EFFECT, MMCommon.MODID);

    public static final DeferredHolder<MobEffect, EffectSunsBlessing> SUNS_BLESSING = REG.register("suns_blessing", EffectSunsBlessing::new);
    public static final DeferredHolder<MobEffect, EffectGeomancy> GEOMANCY = REG.register("geomancy", EffectGeomancy::new);
    public static final DeferredHolder<MobEffect, EffectFrozen> FROZEN = REG.register("frozen", EffectFrozen::new);
    public static final DeferredHolder<MobEffect, EffectPoisonResist> POISON_RESIST = REG.register("poison_resist", EffectPoisonResist::new);
    public static final DeferredHolder<MobEffect, EffectSunblock> SUNBLOCK = REG.register("sunblock", EffectSunblock::new);
    public static final DeferredHolder<MobEffect, EffectMoonsCurse> MOONS_CURSE = REG.register("moons_curse", EffectMoonsCurse::new);
    public static final DeferredHolder<MobEffect, EffectFragility> FRAGILITY = REG.register("fragility", EffectFragility::new);
    public static final DeferredHolder<MobEffect, EffectEclipsed> ECLIPSED = REG.register("eclipsed", EffectEclipsed::new);

    public static void addOrCombineEffect(LivingEntity entity, Holder<MobEffect> effect, int duration, int amplifier, boolean ambient, boolean showParticles) {
        if (effect == null) return;
        MobEffectInstance effectInst = entity.getEffect(effect);
        MobEffectInstance newEffect = new MobEffectInstance(effect, duration, amplifier, ambient, showParticles);
        if (effectInst != null) effectInst.update(newEffect);
        else entity.addEffect(newEffect);
    }
}

package com.bobmowzie.mowziesmobs.server.capability;

import com.bobmowzie.mowziesmobs.MMCommon;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.neoforged.neoforge.attachment.AttachmentType;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;
import net.neoforged.neoforge.registries.NeoForgeRegistries;
import org.jetbrains.annotations.NotNull;

public final class DataHandler {
    // Capabilities are used when these data containers are expected to be accessed by other mods as well
    // (through the capability provider you define which type of object (e.g. entity type) returns null or a data container (data attachment))
    public static final DeferredRegister<AttachmentType<?>> MM_ATTACHMENT_TYPES = DeferredRegister.create(NeoForgeRegistries.ATTACHMENT_TYPES.key(), MMCommon.MODID);

    public static final DeferredHolder<AttachmentType<?>, AttachmentType<FrozenData>> FROZEN_DATA = MM_ATTACHMENT_TYPES.register("frozen_data", () -> AttachmentType.serializable(FrozenData::new).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<LivingData>> LIVING_DATA = MM_ATTACHMENT_TYPES.register("living_data", () -> AttachmentType.serializable(LivingData::new).build());

    public static final DeferredHolder<AttachmentType<?>, AttachmentType<PlayerData>> PLAYER_DATA = MM_ATTACHMENT_TYPES.register("player_data", () -> AttachmentType.serializable(PlayerData::new).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<AbilityData>> ABILITY_DATA = MM_ATTACHMENT_TYPES.register("ability_data", () -> AttachmentType.serializable(AbilityData::new).build());

    // Single point of usage in case additional checks are needed etc.
    public static <T> @NotNull T getData(@NotNull Entity entity, @NotNull DeferredHolder<AttachmentType<?>, AttachmentType<T>> type) {
        if (PLAYER_DATA.equals(type) && !(entity instanceof Player)) {
            // It's basically choosing between checking which entity gets passed into here vs. having a null check for every call of this method
            throw new IllegalArgumentException("Cannot fetch player data for non-player entity of type [" + entity.getType() + "]");
        }

        return entity.getData(type);
    }
}

